@@ -0,0 +1,71 @@
+import { Duration } from 'aws-cdk-lib';
+import { Construct } from 'constructs';
+import * as cw from 'aws-cdk-lib/aws-cloudwatch';
+import * as ecs from 'aws-cdk-lib/aws-ecs';
+
+export interface AlarmStrategy {
+  build(scope: Construct, id: string, service: ecs.FargateService): cw.Alarm[];
+}
+
+export interface AlarmStrategyFactoryOptions {
+  readonly kind: 'standard';
+  readonly overrides?: Record<string, unknown>;
+  readonly hooks?: Array<(alarm: cw.Alarm) => void>;
+}
+
+export class AlarmStrategyFactory {
+  private static registry = new Map<string, () => AlarmStrategy>();
+
+  static register(kind: string, make: () => AlarmStrategy): void {
+    AlarmStrategyFactory.registry.set(kind, make);
+  }
+
+  static create(options: AlarmStrategyFactoryOptions): AlarmStrategy {
+    const make = AlarmStrategyFactory.registry.get(options.kind);
+    if (!make) {
+      throw new Error(`no alarm strategy registered for ${options.kind}`);
+    }
+    const strategy = make();
+    return {
+      build(scope, id, service) {
+        const alarms = strategy.build(scope, id, service);
+        for (const hook of options.hooks ?? []) alarms.forEach(hook);
+        return alarms;
+      },
+    };
+  }
+}
+
+class StandardAlarmStrategy implements AlarmStrategy {
+  build(scope: Construct, id: string, service: ecs.FargateService): cw.Alarm[] {
+    return [
+      new cw.Alarm(scope, `${id}Cpu`, {
+        metric: service.metricCpuUtilization({ period: Duration.minutes(1) }),
+        threshold: 85,
+        evaluationPeriods: 5,
+      }),
+      new cw.Alarm(scope, `${id}Memory`, {
+        metric: service.metricMemoryUtilization({ period: Duration.minutes(1) }),
+        threshold: 90,
+        evaluationPeriods: 5,
+      }),
+    ];
+  }
+}
+
+AlarmStrategyFactory.register('standard', () => new StandardAlarmStrategy());
+
+export interface ServiceAlarmsProps {
+  readonly service: ecs.FargateService;
+  readonly strategy?: AlarmStrategyFactoryOptions;
+}
+
+export class ServiceAlarms extends Construct {
+  readonly alarms: cw.Alarm[];
+
+  constructor(scope: Construct, id: string, props: ServiceAlarmsProps) {
+    super(scope, id);
+    const strategy = AlarmStrategyFactory.create(props.strategy ?? { kind: 'standard' });
+    this.alarms = strategy.build(this, 'Service', props.service);
+  }
+}
